## `src/types.ts`

```typescript
import * as pulumi from "@pulumi/pulumi";

/**
 * Environment-specific configuration for the infrastructure component.
 * Sourced from Pulumi stack config (Pulumi.dev.yaml / Pulumi.prod.yaml).
 */
export interface InfraConfig {
  /** AWS region for primary resources */
  region: string;

  /**
   * S3: Whether to enable cross-region replication (prod only).
   * The replica bucket is created in the specified destination region.
   */
  replicationEnabled: boolean;
  replicationDestinationRegion: string;

  /** RDS instance class (e.g. "db.t3.micro", "db.t3.medium") */
  rdsInstanceClass: string;

  /** RDS: Enable multi-AZ (prod only) */
  rdsMultiAz: boolean;

  /** RDS: Enable storage encryption (prod only per spec) */
  rdsStorageEncrypted: boolean;

  /** RDS: Backup retention in days (minimum 7 per acceptance criteria) */
  rdsBackupRetentionDays: number;

  /** IAM: Use OIDC trust policy (prod) vs. programmatic trust (dev) */
  iamUseOidcTrust: boolean;

  /** IAM: OIDC provider ARN (required when iamUseOidcTrust is true) */
  oidcProviderArn?: string;

  /** IAM: Sub condition key for OIDC (e.g. "sub=system:serviceaccount:ns:sa") */
  oidcSubCondition?: string;

  /** IAM: External ID for STS assume-role (dev) */
  iamExternalId?: string;
}
```

## `src/infra.ts`

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import { InfraConfig } from "./types";

// ---------------------------------------------------------------------------
// Output interface
// ---------------------------------------------------------------------------

export interface InfraOutputs {
  /** Primary S3 bucket */
  bucket: aws.s3.Bucket;
  /** Replica S3 bucket (prod only; undefined in dev) */
  bucketReplica?: aws.s3.Bucket;
  /** RDS PostgreSQL instance */
  rdsInstance: aws.rds.Instance;
  /** IAM role ARN */
  iamRoleArn: pulumi.Output<string>;
  /** KMS key for RDS storage encryption (prod) */
  rdsKmsKey?: aws.kms.Key;
  /** Encrypted DB connection string (secret) */
  connectionString: pulumi.Output<string>;
}

// ---------------------------------------------------------------------------
// ComponentResource
// ---------------------------------------------------------------------------

export class ApplicationInfra extends pulumi.ComponentResource {
  public readonly outputs: InfraOutputs;

  constructor(name: string, args: { config: InfraConfig }, opts?: pulumi.ComponentResourceOptions) {
    super("infra:ApplicationInfra", name, undefined, opts);

    const { config } = args;
    const stackConfig = new pulumi.Config();

    // -------------------------------------------------------------------------
    // Secrets (Pulumi ConfigSecret — never plaintext in VCS)
    // -------------------------------------------------------------------------
    const dbPassword = stackConfig.requireSecret("dbPassword");
    const dbUser = stackConfig.require("dbUser");

    // -------------------------------------------------------------------------
    // S3 Bucket (primary)
    // -------------------------------------------------------------------------
    const bucketName = pulumi.interpolate`${name}-${pulumi.stack}`.apply(s =>
      s.toLowerCase().replace(/[^a-z0-9-]/g, "")
    );

    const bucket = new aws.s3.Bucket(name, {
      bucket: bucketName,
      forceDestroy: false,
      tags: {
        Environment: pulumi.stack,
        ManagedBy: "pulumi",
      },
    }, { parent: this });

    // Versioning
    const versioning = new aws.s3.BucketVersioning(`${name}-versioning`, {
      bucket: bucket.id,
      versioningConfiguration: { status: "Enabled" },
    }, { parent: this });

    // Server-Side Encryption (AES-256)
    const encryption = new aws.s3.BucketServerSideEncryptionConfiguration(`${name}-sse`, {
      bucket: bucket.id,
      rules: [
        {
          applyServerSideEncryptionByDefault: {
            sseAlgorithm: "AES256",
          },
        },
      ],
    }, { parent: this });

    // Block all public access
    const publicAccessBlock = new aws.s3.BucketPublicAccessBlock(`${name}-pub-access`, {
      bucket: bucket.id,
      blockPublicAcls: true,
      blockPublicPolicy: true,
      ignorePublicAcls: true,
      restrictPublicBuckets: true,
    }, { parent: this });

    // -------------------------------------------------------------------------
    // S3 Replication (prod only)
    // -------------------------------------------------------------------------
    let bucketReplica: aws.s3.Bucket | undefined;
    let replicationConfig: aws.s3.BucketReplication | undefined;

    if (config.replicationEnabled) {
      const replicaName = pulumi.interpolate`${name}-${pulumi.stack}-replica`.apply(s =>
        s.toLowerCase().replace(/[^a-z0-9-]/g, "")
      );

      bucketReplica = new aws.s3.Bucket(`${name}-replica`, {
        bucket: replicaName,
        region: config.replicationDestinationRegion,
        tags: {
          Environment: pulumi.stack,
          ManagedBy: "pulumi",
          Purpose: "replica",
        },
      }, { parent: this });

      const replicaVersioning = new aws.s3.BucketVersioning(`${name}-replica-versioning`, {
        bucket: bucketReplica.id,
        versioningConfiguration: { status: "Enabled" },
      }, { parent: this });

      const replicaPublicAccessBlock = new aws.s3.BucketPublicAccessBlock(`${name}-replica-pub-access`, {
        bucket: bucketReplica.id,
        blockPublicAcls: true,
        blockPublicPolicy: true,
        ignorePublicAcls: true,
        restrictPublicBuckets: true,
      }, { parent: this });

      // Replication requires a bucket policy granting s3:ReplicateObject
      const replicaPolicy = new aws.s3.BucketPolicy(`${name}-replica-policy`, {
        bucket: bucketReplica.id,
        policy: aws.s3.BucketReplication
          .getReplicationConfiguration({})
          .then(() => pulumi.jsonStringify({
            Version: "2012-10-17",
            Statement: [
              {
                Effect: "Allow",
                Principal: { Service: "s3.amazonaws.com" },
                Action: ["s3:ReplicateObject", "s3:ReplicateDelete"],
                Resource: bucketReplica!.arn.apply(a => `${a}/*`),
              },
            ],
          })),
      }, { parent: this });

      replicationConfig = new aws.s3.BucketReplication(`${name}-replication`, {
        bucket: bucket.id,
        role: iamRole.arn, // Reuse the IAM role (or create a dedicated one)
        rules: [
          {
            id: "replicate-all",
            status: "Enabled",
            destination: {
              bucket: bucketReplica.arn,
              storageClass: "STANDARD",
            },
          },
        ],
      }, { parent: this, dependsOn: [replicaVersioning, replicaPolicy] });
    }

    // -------------------------------------------------------------------------
    // IAM Role for service accounts
    // -------------------------------------------------------------------------
    let assumeRolePolicy: string;

    if (config.iamUseOidcTrust) {
      // Prod: OIDC federated trust (EKS workload identity)
      assumeRolePolicy = pulumi.jsonStringify({
        Version: "2012-10-17",
        Statement: [
          {
            Effect: "Allow",
            Principal: {
              Federated: config.oidcProviderArn!,
            },
            Action: ["sts:AssumeRoleWithWebIdentity"],
            Condition: {
              StringEquals: {
                [pulumi.interpolate`${config.oidcProviderArn!}/sub`]: config.oidcSubCondition!,
              },
            },
          },
        ],
      });
    } else {
      // Dev: Programmatic access via EC2/STS assume role
      const account = aws.getCallerIdentity({});
      assumeRolePolicy = pulumi.jsonStringify({
        Version: "2012-10-17",
        Statement: [
          {
            Effect: "Allow",
            Principal: {
              Service: "ec2.amazonaws.com",
            },
            Action: "sts:AssumeRole",
          },
          {
            Effect: "Allow",
            Principal: {
              AWS: pulumi.interpolate`arn:aws:iam::${account.accountId}:root`,
            },
            Action: "sts:AssumeRole",
            Condition: config.iamExternalId
              ? { StringEquals: { "sts:ExternalId": config.iamExternalId } }
              : undefined,
          },
        ].filter(Boolean),
      });
    }

    const iamRole = new aws.iam.Role(`${name}-service-role`, {
      name: pulumi.interpolate`${name}-${pulumi.stack}-service`,
      assumeRolePolicy: assumeRolePolicy,
      maxSessionDuration: 3600,
      tags: {
        Environment: pulumi.stack,
        ManagedBy: "pulumi",
      },
    }, { parent: this });

    // Attach least-privilege policies (no wildcard actions on prod)
    const bucketArn = bucket.arn.apply(a => a); // arn:aws:s3:::bucket

    // S3 access scoped to specific bucket
    const s3Policy = new aws.iam.Policy(`${name}-s3-policy`, {
      name: pulumi.interpolate`${name}-${pulumi.stack}-s3`,
      policy: pulumi.jsonStringify({
        Version: "2012-10-17",
        Statement: [
          {
            Effect: "Allow",
            Action: [
              "s3:GetObject",
              "s3:PutObject",
              "s3:ListBucket",
              "s3:DeleteObject",
              "s3:GetBucketVersioning",
            ],
            Resource: [
              bucketArn,
              bucketArn.apply(a => `${a}/*`),
            ],
          },
        ],
      }),
    }, { parent: this });

    const s3PolicyAttachment = new aws.iam.RolePolicyAttachment(`${name}-s3-attach`, {
      role: iamRole.name,
      policyArn: s3Policy.arn,
    }, { parent: this });

    // -------------------------------------------------------------------------
    // KMS Key for RDS (prod — encryption at rest)
    // -------------------------------------------------------------------------
    let rdsKmsKey: aws.kms.Key | undefined;
    let kmsKeyArn: pulumi.Output<string> | undefined;

    if (config.rdsStorageEncrypted) {
      rdsKmsKey = new aws.kms.Key(`${name}-rds-kms`, {
        description: `KMS key for RDS encryption - ${pulumi.stack}`,
        enableKeyRotation: true,
        deletionWindowInDays: 30,
        tags: {
          Environment: pulumi.stack,
          ManagedBy: "pulumi",
        },
      }, { parent: this });

      kmsKeyArn = rdsKmsKey.arn;
    }

    // -------------------------------------------------------------------------
    // RDS PostgreSQL Instance
    // -------------------------------------------------------------------------
    const subnetGroup = new aws.rds.SubnetGroup(`${name}-subnet-group`, {
      name: pulumi.interpolate`${name}-${pulumi.stack}-db`,
      subnetIds: stackConfig.requireObject<string[]>("subnetIds"),
      tags: {
        Environment: pulumi.stack,
      },
    }, { parent: this });

    const securityGroup = new aws.securitygroup.Group(`${name}-db-sg`, {
      name: pulumi.interpolate`${name}-${pulumi.stack}-db`,
      description: "Allow PostgreSQL traffic from application subnet only",
      vpcId: stackConfig.require("vpcId"),
      ingress: [
        {
          protocol: "tcp",
          fromPort: 5432,
          toPort: 5432,
          cidrBlocks: ["10.0.0.0/8"], // Restrict to internal VPC range
          description: "PostgreSQL from app tier",
        },
      ],
      egress: [],
      tags: {
        Environment: pulumi.stack,
      },
    }, { parent: this });

    const rdsInstance = new aws.rds.Instance(`${name}-postgres`, {
      identifier: pulumi.interpolate`${name}-${pulumi.stack}-postgres`,
      engine: "postgres",
      engineVersion: "16.3",
      instanceClass: config.rdsInstanceClass,
      allocatedStorage: config.rdsInstanceClass === "db.t3.micro" ? 20 : 100,
      storageType: "gp3",
      storageEncrypted: config.rdsStorageEncrypted,
      kmsKeyId: kmsKeyArn,
      multiAz: config.rdsMultiAz,
      dbName: "appdb",
      username: dbUser,
      password: dbPassword,
      skipFinalSnapshot: false,
      finalSnapshotIdentifier: pulumi.interpolate`${name}-${pulumi.stack}-final`,
      deletionProtection: true,
      backupRetentionPeriod: config.rdsBackupRetentionDays,
      backupWindow: "03:00-04:00",
      maintenanceWindow: "sun:04:00-sun:05:00",
      publiclyAccessible: false,
      vpcSecurityGroupIds: [securityGroup.id],
      dbSubnetGroupName: subnetGroup.name,
      autoMinorVersionUpgrade: true,
      performanceInsightsEnabled: true,
      tags: {
        Environment: pulumi.stack,
        ManagedBy: "pulumi",
      },
    }, { parent: this });

    // -------------------------------------------------------------------------
    // Construct secret connection string
    // -------------------------------------------------------------------------
    const connectionString = pulumi
      .all([rdsInstance.address, rdsInstance.port, dbUser, dbPassword, rdsInstance.dbName])
      .apply(([host, port, user, pass, dbName]) =>
        pulumi.secret(`postgres://${user}:${pass}@${host}:${port}/${dbName}?sslmode=require`)
      );

    // -------------------------------------------------------------------------
    // Expose outputs
    // -------------------------------------------------------------------------
    this.outputs = {
      bucket,
      bucketReplica,
      rdsInstance,
      iamRoleArn: iamRole.arn,
      rdsKmsKey,
      connectionString,
    };

    this.registerOutputs({
      bucketArn: bucket.arn,
      rdsEndpoint: rdsInstance.address,
      iamRoleArn: iamRole.arn,
    });
  }
}
```

## `src/index.ts`

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import { ApplicationInfra } from "./infra";
import { InfraConfig } from "./types";

// ---------------------------------------------------------------------------
// Read stack config into InfraConfig
// ---------------------------------------------------------------------------
const stackConfig = new pulumi.Config();
const region = stackConfig.require("region");

aws.configure({ region });

const infraConfig: InfraConfig = {
  region,
  replicationEnabled: stackConfig.getBoolean("replicationEnabled") ?? false,
  replicationDestinationRegion: stackConfig.get("replicationDestinationRegion") ?? "us-west-2",
  rdsInstanceClass: stackConfig.require("rdsInstanceClass"),
  rdsMultiAz: stackConfig.getBoolean("rdsMultiAz") ?? false,
  rdsStorageEncrypted: stackConfig.getBoolean("rdsStorageEncrypted") ?? false,
  rdsBackupRetentionDays: stackConfig.getNumber("rdsBackupRetentionDays") ?? 7,
  iamUseOidcTrust: stackConfig.getBoolean("iamUseOidcTrust") ?? false,
  oidcProviderArn: stackConfig.get("oidcProviderArn"),
  oidcSubCondition: stackConfig.get("oidcSubCondition"),
  iamExternalId: stackConfig.get("iamExternalId"),
};

// ---------------------------------------------------------------------------
// Instantiate the component
// ---------------------------------------------------------------------------
const infra = new ApplicationInfra("app-infra", {
  config: infraConfig,
});

// ---------------------------------------------------------------------------
// Stack outputs
// ---------------------------------------------------------------------------
export const bucketName = infra.outputs.bucket.bucket;
export const rdsEndpoint = infra.outputs.rdsInstance.address;
export const iamRoleArn = infra.outputs.iamRoleArn;
export const connectionString = infra.outputs.connectionString;
export const bucketArn = infra.outputs.bucket.arn;
```

